import {taskSwipeAttrs} from './task-swipe.js';
import {entityIcon} from './entity-icons.js';
import {habitGoalMet,habitStreaks} from './habit-streaks.js';
import {period,addDays,today,dateOf} from './model.js';
import {taskArea,projectLabel,projectArea,isProjectArchived,isProjectCompleted,isTaskActive} from './domain.js';
import {plannedDates,overdueTasks} from './day-flow.js';
import {recurrenceLabel} from './recurrence.js';
import {kanbanHTML,taskViewToggle} from './kanban.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(s,o={day:'numeric',month:'short'})=>dateOf(s).toLocaleDateString('ru-RU',{...o,timeZone:'UTC'});
const num=n=>Number(n||0).toLocaleString('ru-RU',{maximumFractionDigits:3});
const attrs=(action,id)=>`data-action="${action}" data-id="${esc(id)}"`;
export function sidebarTreeHTML(state,{page,entityId,expanded}){
 const item=(kind,e,children='')=>{const key=kind+':'+e.id,open=expanded[key]??kind==='area',active=entityId===e.id&&page===(kind==='area'?'areas':'projects');return `<li class="space-tree-item ${active?'active':''}"><div class="space-tree-row">${children?`<button class="space-tree-toggle" data-action="tree-toggle" data-key="${esc(key)}" aria-label="${open?'Свернуть':'Развернуть'} ${esc(e.name)}" aria-expanded="${open}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></button>`:'<span class="space-tree-spacer"></span>'}<button class="space-tree-title" data-tree-open="${kind}" data-id="${esc(e.id)}" data-key="${esc(key)}" data-has-children="${!!children}" title="${esc(e.name)}" ${active?'aria-current="page"':''}><span class="space-tree-symbol">${entityIcon(e,kind)}</span><span class="space-tree-name">${esc(e.name)}${kind==='project'&&isProjectCompleted(state,e)?'<span class="tree-project-done" title="Проект завершён">✓</span>':''}</span></button></div>${children?`<ul ${open?'':'hidden'}>${children}</ul>`:''}</li>`;};
 const activeProjects=state.projects.filter(p=>!isProjectArchived(state,p));
 const project=p=>item('project',p,activeProjects.filter(c=>c.parentId===p.id).map(c=>item('project',c)).join(''));
 const areas=state.areas.map(a=>item('area',a,activeProjects.filter(p=>!p.parentId&&projectArea(state,p)===a.id).map(project).join(''))).join('');
 const unassigned=activeProjects.filter(p=>!p.parentId&&!p.areaId).map(project).join(''),hasInbox=state.tasks.some(t=>!t.archived&&!taskArea(state,t))||!!unassigned;
 return `<ul class="space-tree-root">${areas}${hasInbox?item('area',{id:'__inbox',name:'Без зоны'},unassigned):''}</ul><div class="tree-create"><button class="text-button" data-action="new-area" title="Новая зона">+ <span>Зона</span></button><button class="text-button" data-action="new-project" title="Новый проект">+ <span>Проект</span></button></div><button class="text-button tree-archive" data-action="project-archive">Архив проектов <span class="count">${state.projects.filter(p=>isProjectArchived(state,p)).length}</span></button>`;
}
function taskMeta(state,t){const dates=plannedDates(state,t.id),late=!t.done&&!t.cancelled&&!t.skipped&&!t.someday&&(t.due&&t.due<today()||dates.some(d=>d<today()));return `<div class="flow-task-meta">${t.projectId?`<span>${esc(projectLabel(state,t.projectId))}</span>`:''}${t.due?`<span>Срок ${fmt(t.due)}</span>`:''}${late?'<span class="overdue-tag">Просрочена</span>':''}${dates.length?`<span title="${esc(dates.map(d=>fmt(d)).join(', '))}">План: ${fmt(dates.at(-1))}${dates.length>1?' · ещё '+(dates.length-1):''}</span>`:''}${t.skipped?'<span>Пропущена · история</span>':''}</div>`;}
export function flowTaskHTML(state,t,{select=false,readonly=false,history=false}={}){
 const archivedProject=isProjectArchived(state,t.projectId);readonly||=archivedProject||isProjectCompleted(state,t.projectId);
 return `<div class="flow-task ${t.done?'is-done':''} ${history?'is-history':''}" data-task-id="${esc(t.id)}" ${readonly?'':taskSwipeAttrs(state,t)}><button class="task-check ${t.done?'checked':''}" ${attrs('toggle-done',t.id)} aria-label="${t.done?'Вернуть в работу':'Завершить'}: ${esc(t.title)}" aria-pressed="${t.done}" ${readonly||t.cancelled||t.skipped||t.archived||t.someday?'disabled':''}>${t.done?'✓':t.cancelled||t.skipped?'−':''}</button><div class="flow-task-body"><button class="task-title ${t.done?'completed':''}" ${attrs('edit-task',t.id)} ${readonly?'disabled':''}>${esc(t.title)}</button>${taskMeta(state,t)}</div>${t.someday?`<span class="task-status someday">Когда-нибудь</span>${!readonly?`<button class="text-button" ${attrs('activate-task',t.id)}>В работу</button>`:''}`:''}${select?`<button class="select-task" ${attrs('add-day-task',t.id)} aria-label="В план дня: ${esc(t.title)}">+</button>`:''}${t.recurrence!=='none'?`<button ${readonly?'disabled':''} class="repeat-config-button" ${attrs('edit-repeat',t.id)} aria-label="Настроить повторение: ${esc(t.title)}"><span>${esc(recurrenceLabel(t))}${t.repeatFrom==='due'&&t.due?' · '+fmt(t.due,{weekday:'short'}):''}</span> ⇄</button>`:''}</div>`;
}
export function overdueHTML(state,day){const plan=state.plans['day:'+day],ids=new Set(plan?.snapshot?.items.map(t=>t.id)||plan?.selected||[]),rows=overdueTasks(state,day).filter(r=>!ids.has(r.task.id));return `<details class="flow-section overdue-section" data-collapse-key="overdue:${day}"><summary>Просроченные <span class="count">${rows.length}</span></summary><div class="flow-section-body">${rows.length?rows.map(({task})=>flowTaskHTML(state,task,{select:!plan?.snapshot})).join(''):'<p class="flow-empty">Нет просроченных задач.</p>'}</div></details>`;}
export function todayHTML(state){
 const day=today(),plan=state.plans['day:'+day],fixed=!!plan?.snapshot,items=plan?.snapshot?.items||[],rows=items.map(item=>({item,live:state.tasks.find(t=>t.id===item.id)})),extras=(plan?.overplan||[]).map(id=>state.tasks.find(t=>t.id===id)).filter(Boolean);
 const plannedRows=rows.length?rows.map(({item,live})=>live?flowTaskHTML(state,live):`<div class="flow-empty">${esc(item.title)} · исходная задача отсутствует</div>`).join(''):'<p class="flow-empty">В исходном плане нет задач.</p>';
 const overplanRows=extras.length?extras.map(t=>flowTaskHTML(state,t)).join(''):'<p class="flow-empty">Здесь будут задачи, добавленные после фиксации.</p>';
 return `<div class="today-heading"><div><h1>Сегодня</h1><p>${fmt(day,{weekday:'long',day:'numeric',month:'long'})}</p></div><button class="text-button" data-action="open-day-journal">${fixed?'План и итоги дня ↗':'Собрать план дня ↗'}</button></div>${todayHabitStripHTML(state,day)}${!fixed?'<div class="today-no-plan"><h2>Начните с плана дня</h2><p>Выберите задачи в Journal и зафиксируйте намерение.</p><button class="primary-button" data-action="open-day-journal">Перейти к планированию</button></div>':`<div class="today-section"><details class="flow-section today-tasks" data-collapse-key="today:${day}:plan" open><summary>По плану <span class="count">${rows.filter(r=>r.live?.done&&r.live.completedAt===day).length} / ${rows.length}</span></summary><div class="flow-section-body">${plannedRows}</div></details><span class="badge frozen today-section-status">◈ Зафиксирован</span></div><div class="today-section"><details class="flow-section today-tasks today-overplan" data-collapse-key="today:${day}:overplan" open><summary>Вне плана <span class="count">${extras.length}</span></summary><div class="flow-section-body">${overplanRows}</div></details><button class="text-button today-section-add" data-action="today-add">+ Добавить</button></div>`}`;
}
export function todayPickerHTML(state,weekly){const plan=state.plans['day:'+today()],ids=new Set([...(plan?.snapshot?.items||[]).map(t=>t.id),...(plan?.overplan||[])]),rows=weekly.filter(t=>!ids.has(t.id)&&isTaskActive(state,t)&&!t.done&&!t.cancelled);return `<h2>Добавить вне плана</h2><div class="modal-actions today-add-actions"><button class="primary-button" data-action="today-new-task">+ Новая задача</button></div><h3 class="picker-title">Из недельного плана</h3>${rows.length?rows.map(t=>`<div class="picker-task"><span>${esc(t.title)}</span><button class="select-task" ${attrs('today-pick',t.id)} aria-label="Взять на сегодня: ${esc(t.title)}">+</button></div>`).join(''):'<p class="flow-empty">Нет доступных задач недели.</p>'}`;}
const section=(key,title,body,count,actions='')=>`<details class="flow-section" data-collapse-key="${esc(key)}" open><summary>${title} <span class="count">${count}</span></summary><div class="flow-section-body">${actions}${body}</div></details>`;
export function projectArchiveHTML(state){
 const projects=state.projects.filter(p=>isProjectArchived(state,p));
 return `<div class="scope-heading"><h1>Архив проектов</h1><button class="text-button" data-action="page" data-page="zones">Зоны и проекты ↗</button></div><p class="project-archive-notice">Архив сохраняет задачи и историю проектов. Восстановите проект, чтобы снова выбирать его задачи в планы.</p>${projects.length?projects.map(p=>{const parent=state.projects.find(parent=>parent.id===p.parentId),inherited=parent?.archived,area=state.areas.find(a=>a.id===projectArea(state,p));return `<div class="project-archive-row"><button class="project-archive-open" ${attrs('open-project',p.id)}><span>${entityIcon(p,'project')}${esc(projectLabel(state,p.id))}</span><small>${esc(area?.name||'Без зоны')}${inherited?' · в архиве вместе с родителем':''}</small></button><button class="secondary-button" ${attrs('restore-project',inherited?parent.id:p.id)}>${inherited?'Восстановить родителя':'Восстановить'}</button><button class="text-button" ${attrs('delete-project',p.id)}>Удалить</button></div>`;}).join(''):'<p class="flow-empty">В архиве пока нет проектов.</p>'}`;
}
export function scopeHTML(state,{page,entityId,layout='table'}){
 if(page==='projects'&&entityId==='__archive')return projectArchiveHTML(state);
 const isProject=page==='projects',entity=isProject?state.projects.find(p=>p.id===entityId):state.areas.find(a=>a.id===entityId),inbox=!isProject&&entityId==='__inbox',id=entity?.id||'',name=entity?.name||(inbox?'Без зоны':isProject?'Проект':'Зоны ответственности');
 if(!entity&&!inbox)return `<div class="collection-heading"><h1>${esc(name)}</h1><button class="primary-button" data-action="new-${isProject?'project':'area'}">+ Создать</button></div><p class="flow-empty">Выберите ${isProject?'проект':'зону'} в боковой панели.</p>`;
 const archived=isProject&&isProjectArchived(state,entity),closed=isProject&&isProjectCompleted(state,entity),parent=state.projects.find(p=>p.id===entity?.parentId),direct=state.tasks.filter(t=>isProject?t.projectId===id:!t.projectId&&(t.areaId||null)===(inbox?null:id)),active=direct.filter(t=>!t.archived),single=active.filter(t=>!t.someday&&t.recurrence==='none'),recurring=active.filter(t=>!t.someday&&t.recurrence!=='none'&&!t.done&&!t.cancelled),someday=active.filter(t=>t.someday),history=direct.filter(t=>t.recurrence!=='none'&&(t.done||t.cancelled||t.skipped)),projects=state.projects.filter(p=>(isProject?p.parentId===id:!p.parentId&&(p.areaId||null)===(inbox?null:id))&&(archived||!isProjectArchived(state,p))),linkAttrs=isProject?`data-project="${esc(id)}"`:`data-area="${esc(id)}"`;
 const header=`<div class="scope-heading"><div>${isProject&&entity.parentId?`<div class="scope-path">${esc(parent?.name||'')}</div>`:''}<h1>${entityIcon(entity,isProject?'project':'area')}${esc(name)}</h1></div><div class="scope-actions">${archived?'<span class="badge">В архиве</span>':closed?`<span class="badge frozen">Завершён</span><button class="secondary-button" ${attrs('reopen-project',parent?.completedAt?parent.id:id)}>${parent?.completedAt?'Открыть родительский проект':'Открыть снова'}</button>`:`${isProject?taskViewToggle(layout):''}${isProject?`<button class="text-button" data-action="complete-project" data-id="${esc(id)}">Завершить</button>`:''}${entity?`<button class="secondary-button" data-action="edit-${isProject?'project':'area'}" data-id="${esc(id)}">Изменить</button>`:''}<button class="primary-button" data-action="new-task" ${linkAttrs}>+ Задача</button>`}</div></div>`;
 const childCards=projects.length?projects.map(p=>`<button class="scope-project" data-action="open-project" data-id="${esc(p.id)}"><span>${entityIcon(p,'project')}${esc(p.name)}${isProjectArchived(state,p)?' · архив':isProjectCompleted(state,p)?' · завершён':''}</span><span>›</span></button>`).join(''):'<p class="flow-empty">Пока нет проектов.</p>';
 if(archived)return header+`<p class="project-archive-notice">Проект в архиве. Задачи и снимки планов сохранены; новые повторения приостановлены.</p><div class="archived-project-actions"><button class="primary-button" ${attrs('restore-project',parent?.archived?parent.id:id)}>${parent?.archived?'Восстановить родительский проект':'Восстановить проект'}</button><button class="secondary-button" data-action="project-archive">Архив проектов</button><button class="danger-button" ${attrs('delete-project',id)}>Удалить проект</button></div>`+section('archive:'+id+':tasks','Задачи проекта',direct.map(t=>flowTaskHTML(state,t,{readonly:true})).join('')||'<p class="flow-empty">Пока нет задач.</p>',direct.length)+(projects.length?section('archive:'+id+':children','Подпроекты',childCards,projects.length):'');
 if(closed)return header+`<p class="project-archive-notice">Цель завершена вручную. Задачи и планы сохранены; повторения приостановлены.</p>`+section('closed:'+id+':tasks','Задачи проекта',direct.map(t=>flowTaskHTML(state,t,{readonly:true})).join('')||'<p class="flow-empty">Пока нет задач.</p>',direct.length)+(projects.length?section('closed:'+id+':children','Подпроекты',childCards,projects.length):'');
 const tasks=isProject&&layout==='kanban'?kanbanHTML(state,active,id):section(page+':'+id+':single','Самостоятельные задачи',single.map(t=>flowTaskHTML(state,t)).join('')||'<p class="flow-empty">Пока нет задач.</p>',single.length)+section(page+':'+id+':repeat','Повторяющиеся задачи',`<button class="text-button section-add-repeat" data-action="new-recurring" ${linkAttrs}>+ Повторяющаяся задача</button>${recurring.map(t=>flowTaskHTML(state,t)).join('')||'<p class="flow-empty">Пока нет повторений.</p>'}${history.length?`<details class="repeat-history flow-section" data-collapse-key="repeat-history:${esc(id)}"><summary>История экземпляров · ${history.length}</summary><div class="flow-section-body">${history.map(t=>flowTaskHTML(state,t,{readonly:true,history:true})).join('')}</div></details>`:''}`,recurring.length);
 const childActions=isProject&&entity.parentId?'':`<button class="text-button section-add-repeat" data-action="new-project" ${isProject?`data-parent="${esc(id)}"`:inbox?'':`data-area="${esc(id)}"`}>+ ${isProject?'Подпроект':'Проект'}</button>`;
 return header+tasks+(!(isProject&&layout==='kanban')?section(page+':'+id+':someday','Когда-нибудь',someday.map(t=>flowTaskHTML(state,t)).join('')||'<p class="flow-empty">Отложенные действия появятся здесь.</p>',someday.length):'')+(!isProject||!entity.parentId?section(page+':'+id+':children',isProject?'Подпроекты':'Проекты',childActions+childCards,projects.length):'');
}
function habitCell(state,h,day,readonly=false){const e=state.habitEntries[day]?.[h.id],v=e?.value||0,target=e?.target??h.target,disabled=readonly||day>today()||!!h.archivedOn&&day>=h.archivedOn,pct=Math.min(100,v/target*100);return `<button class="habit-day-cell ${v>=target?'goal-met':''} ${day===today()?'is-today':''}" ${attrs('habit-increment',h.id)} data-date="${day}" data-hold-habit="true" style="--habit-percent:${pct}%" ${disabled?'disabled':''} aria-label="${esc(h.name)}, ${fmt(day)}: ${num(v)} из ${num(target)} ${esc(e?.unit??h.unit)}. Прибавить ${num(h.step)}" title="${num(v)} / ${num(target)} ${esc(e?.unit??h.unit)}; удерживайте для правки"><span>${e?num(v):''}</span></button>`;}
export function habitWeekHTML(state,day,{archiveOpen=false}={}){
 const week=period('week',day),dates=Array.from({length:7},(_,i)=>addDays(week.start,i)),active=state.habits.filter(h=>!h.archivedOn),archived=state.habits.filter(h=>h.archivedOn);
 const table=(habits,readonly=false)=>`<div class="habit-week-scroller"><table class="habit-week-table"><thead><tr><th><span class="visually-hidden">Привычка</span></th>${dates.map(d=>`<th class="${d===today()?'is-today':''}"><span>${fmt(d,{weekday:'short'})}</span><b>${fmt(d,{day:'numeric'})}</b></th>`).join('')}</tr></thead><tbody>${habits.map(h=>{const streak=habitStreaks(state,h);return `<tr><th scope="row"><button ${attrs('edit-habit',h.id)}><span class="habit-row-symbol">${entityIcon(h,'habit')}</span><span>${esc(h.name)}<small>${num(h.target)} ${esc(h.unit)} · шаг ${num(h.step)}</small><span class="habit-streaks"><span title="Дней подряд с достигнутой целью. Незавершённый сегодняшний день не обрывает вчерашнюю серию.">Текущая серия <b>${streak.current}</b></span><span title="Максимум дней подряд за всю историю привычки">Рекорд <b>${streak.best}</b></span></span></span></button></th>${dates.map((d,i)=>`<td class="${i<6&&habitGoalMet(state,h,d)&&habitGoalMet(state,h,dates[i+1])?'habit-chain-next':''}">${habitCell(state,h,d,readonly)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;
 return `<div class="habit-week-heading"><h1>Привычки</h1><div class="habit-week-navigation"><button class="icon-button" data-action="habit-week-prev" aria-label="Предыдущая неделя">‹</button><strong>${fmt(week.start)} — ${fmt(week.end)}</strong><button class="icon-button" data-action="habit-week-next" aria-label="Следующая неделя">›</button><button class="text-button" data-action="habit-week-today">Сегодня</button></div></div>${active.length?table(active):'<p class="flow-empty">Добавьте первую привычку с целью и шагом.</p>'}<button class="secondary-button habit-week-add" data-action="new-habit">+ Добавить новую привычку</button><p class="habit-input-hint">Нажатие — прибавить шаг. Удержание или Shift + Enter — точное значение.</p><details class="habit-archive flow-section" id="habit-archive" ${archiveOpen?'open':''}><summary>Архивные привычки <span class="count">${archived.length}</span></summary><div class="flow-section-body">${archived.length?table(archived,false):'<p class="flow-empty">Архив пуст.</p>'}</div></details>`;
}
export function todayHabitStripHTML(state,day){const habits=state.habits.filter(h=>!h.archivedOn);return habits.length?`<div class="today-habit-strip" aria-label="Привычки сегодня">${habits.map(h=>{const e=state.habitEntries[day]?.[h.id],v=e?.value||0,target=e?.target??h.target;return `<button class="today-habit-counter ${v>=target?'goal-met':''}" ${attrs('habit-increment',h.id)} data-date="${day}" data-hold-habit="true" aria-label="${esc(h.name)}: ${num(v)} ${esc(h.unit)}, прибавить ${num(h.step)}"><span class="today-habit-name">${entityIcon(h,'habit')}${esc(h.name)}</span><strong>${num(v)} <small>/ ${num(target)} ${esc(h.unit)}</small></strong><b>+${num(h.step)}</b></button>`;}).join('')}</div>`:'';}
